{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C27"],
      "claim": "The query is eprosartan, a diacid angiotensin-receptor blocker; the closest retrieved analogue fimasartan has an absolute oral bioavailability of 18.6% in healthy subjects, below the 20% threshold, supporting low F for this polar diacid class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Olmesartan medoxomil has an absolute bioavailability of about 26%, but it is an ester prodrug and less polar than the query, so it does not override the low-F evidence.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C16"],
      "claim": "Telmisartan has an absolute bioavailability of 42.4% in healthy volunteers, but it contains only one carboxylate and a more lipophilic benzimidazole/biphenyl scaffold, making it less transferable to the diacid query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C24"],
      "claim": "Irbesartan has an absolute bioavailability of 86.62%, but it lacks the query's two free carboxylic acids and has a more lipophilic tetrazole/spiro core, so its high F is not directly transferable.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low: the query is eprosartan, a non-prodrug ARB with two free carboxylates and a thiophene-containing acrylic acid. The closest retrieved analogue fimasartan is below the 20% threshold (18.6%), and the high-F ARB analogues are less transferable because they are prodrugs or contain only one acidic/lipophilic group. Known human data for eprosartan are consistent with low absolute oral bioavailability.",
  "evidence_gaps": [
    "No direct human absolute bioavailability record for eprosartan was retrieved; all retrieved analogues have Morgan similarity below 0.27.",
    "High-F analogues differ substantially in ionization state, prodrug status, and lipophilicity, limiting direct transfer to the diacid query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

